import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash) public {
        vm.assume(hash != bytes32(0));
        vm.deal(address(this), 1 ether);
        c.lockInGuess{value: 1 ether}(hash);

        // After lockInGuess, the predicted block is block.number + 1
        // To make settle() fail due to guess mismatch, we need blockhash(predictedBlock) != hash
        // This is true with high probability if we mine a block with random hash
        // But we can't control blockhash, so we use vm.warp and vm.roll to advance
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 1);

        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // The reference contract only pays 2 ether if guess matches blockhash
        // Since we don't know the actual blockhash, the correct behavior is that settle()
        // should revert when guess doesn't match (which is always true for a random hash)
        // But to avoid flakiness, we check the invariant:
        // After lockInGuess, calling settle() must not increase the caller's balance
        // without the guess matching the blockhash (which we cannot guarantee)

        assertTrue(!success, "settle() should revert because guess cannot match blockhash");
    }
}

